### CLI login/logout/status subcommands and stdin API key piping

Source: https://github.com/openai/codex/blob/main/codex-rs/cli/src/main.rs

Defines `codex login` (with `--with-api-key` for stdin piping and `status` subcommand) and `codex logout` CLI commands. The `read_api_key_from_stdin()` function checks `is_terminal()` and reads from pipe, showing the exact command to use.

```rust
    /// Manage login.
    Login(LoginCommand),

    /// Remove stored authentication credentials.
    Logout(LogoutCommand),

// ...

struct LoginCommand {
    #[arg(
        long = "with-api-key",
        help = "Read the API key from stdin (e.g. `printenv OPENAI_API_KEY | codex login --with-api-key`)"
    )]
    with_api_key: bool,
    // ...
    #[command(subcommand)]
    action: Option<LoginSubcommand>,
}

enum LoginSubcommand {
    /// Show login status.
    Status,
}

// ...

pub fn read_api_key_from_stdin() -> String {
    read_stdin_secret(
        "--with-api-key expects the API key on stdin. Try piping it, e.g. `printenv OPENAI_API_KEY | codex login --with-api-key`.",
        "Reading API key from stdin...",
        "No API key provided via stdin.",
    )
}

fn read_stdin_secret(terminal_message: &str, reading_message: &str, empty_message: &str) -> String {
    let mut stdin = std::io::stdin();
    if stdin.is_terminal() {
        eprintln!("{terminal_message}");
        std::process::exit(1);
    }
    eprintln!("{reading_message}");
    let mut buffer = String::new();
    if let Err(err) = stdin.read_to_string(&mut buffer) {
        eprintln!("Failed to read stdin: {err}");
        std::process::exit(1);
    }
    let secret = buffer.trim().to_string();
    if secret.is_empty() {
        eprintln!("{empty_message}");
        std::process::exit(1);
    }
    secret
}
```

